fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // Only need to check parent indices 0..n/2 (integer division)
    for i in 0..n / 2 {
        let left = 2 * i + 1;
        let right = 2 * i + 2;

        // If left child exists and is smaller than parent, not a min-heap
        if left < n && a[i] > a[left] {
            return false;
        }

        // If right child exists and is smaller than parent, not a min-heap
        if right < n && a[i] > a[right] {
            return false;
        }
    }
    true
}

